degradation.apply:
perl -0pi -e 's/(def {{transform_function}}\([^)]*\)[^:]*:
)/$1    globals()["_sb_drop"] = True
/; s/(return\s+)(\w+)(\s*
)/$1$2.head(len($2) - 1) if globals().get("_sb_drop") and hasattr($2, "head") else $2$3/' {{transform_module}}

